/** Değişken içeren kalıplar: [desen, çeviri] */
export const ES_DESEN: [RegExp, (m: RegExpExecArray, t: (s: string) => string) => string][] = [
  [/^Sulanmayan (.+) için temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `Necesidad básica de nitrógeno para ${t(b(m[1])).toLowerCase()} sin riego: ${m[2]} kg/da.`; }], /* tahil */
  [/^(\d+) su verilen (.+) daha yüksek verim verir; temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `${((x) => x.charAt(0).toLocaleUpperCase() + x.slice(1))(t(b(m[2])))} con ${m[1]} riegos rinde más; necesidad básica de nitrógeno ${m[3]} kg/da.`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak kendiliğinden az azot verir, azot hedefi ([\d.,]+) kg\/da artırıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Materia orgánica ${m[1]} % (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): el suelo aporta poco nitrógeno por sí mismo, el objetivo de nitrógeno se subió ${m[3]} kg/da (total ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak azotun bir kısmını kendisi verir, azot hedefi ([\d.,]+) kg\/da azaltıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Materia orgánica ${m[1]} % (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): el suelo aporta parte del nitrógeno, el objetivo de nitrógeno se bajó ${m[3]} kg/da (total ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \(orta\): azot hedefi değiştirilmedi \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Materia orgánica ${m[1]} % (medio): objetivo de nitrógeno sin cambios (total ${m[2]} kg/da).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): ekimde ([\d.,]+) kg\/da saf fosfor \(P₂O₅\) verilir\.$/, (m) => { return `Fósforo ${m[1]} kg/da (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): en la siembra se aportan ${m[3]} kg/da de fósforo puro (P₂O₅).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): fosforlu gübreye gerek yok\.$/, (m) => { return `Fósforo ${m[1]} kg/da (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): no hace falta abono fosfatado.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): ([\d.,]+) kg\/da saf potasyum \(K₂O\) eklendi\.$/, (m) => { return `Potasio ${m[1]} kg/da (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): se añadieron ${m[3]} kg/da de potasio puro (K₂O).`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): potasyumlu gübreye gerek yok\.$/, (m) => { return `Potasio ${m[1]} kg/da (${({"çok az": "muy bajo", "az": "bajo", "orta": "medio", "iyi": "bueno", "yüksek": "alto", "çok yüksek": "muy alto", "yeterli": "suficiente"} as Record<string, string>)[m[2]] ?? m[2]}): no hace falta abono potásico.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(düşük\): taban gübresi çinkolu seçildi, yapraktan çinko önemli\.$/, (m) => { return `Zinc ${m[1]} mg/kg (bajo): se eligió un abono de fondo con zinc; el zinc foliar es importante.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(yeterli\)\.$/, (m) => { return `Zinc ${m[1]} mg/kg (suficiente).`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(düşük\): kanola bora çok ihtiyaç duyar; tomurcuk ve çiçeklenmedeki yapraktan bor \(MICROSENSE Ca & B\) uygulamalarını atlamayın\.$/, (m) => { return `Boro ${m[1]} mg/kg (bajo): la colza necesita mucho boro; no omita el boro foliar (MICROSENSE Ca & B) en botón y floración.`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(yeterli\); yapraktan bor yine de çiçek tutumunu destekler\.$/, (m) => { return `Boro ${m[1]} mg/kg (suficiente); el boro foliar sigue favoreciendo el cuajado.`; }], /* tahil */
  [/^Kanola kükürde çok ihtiyaç duyar \(yaklaşık 4 kg\/da\); plandaki gübreler ≈ ([\d.,]+) kg\/da veriyor, kapsül döneminde yapraktan potasyum ve kükürt uygulamasını atlamayın\.$/, (m) => { return `La colza necesita mucho azufre (unos 4 kg/da); los abonos del plan aportan ≈ ${m[1]} kg/da, no omita el potasio y el azufre foliares en la fase de silicuas.`; }], /* tahil */
  [/^Bezelye baklagildir; azotun çoğunu kökündeki bakterilerden alır\. Yalnızca ([\d.,]+) kg\/da başlangıç azotu verilir\.$/, (m) => { return `El guisante es una leguminosa y obtiene la mayor parte de su nitrógeno de las bacterias de sus raíces. Solo se aportan ${m[1]} kg/da de nitrógeno inicial.`; }], /* tahil */
  [/^Kireç %([\d.,]+): çinko ve fosfor alımı zorlaşır; fosfor çinkolu taban gübresiyle, azotun bir kısmı kükürtlü gübreyle \(ör\. amonyum sülfat\) verilir\.$/, (m) => `Caliza ${m[1]} %: se dificulta la absorción de zinc y fósforo; el fósforo se aporta con abono de fondo con zinc y parte del nitrógeno con un abono azufrado (p. ej. sulfato amónico).`],
  [/^en az (.+)$/, (m) => `mínimo ${m[1]}`],
  [/^en çok (.+)$/, (m) => `máximo ${m[1]}`],
  [/^Bünye: (.+)$/, (m) => `Textura: ${m[1]}`],
  [/^(\d+) saat$/, (m) => `${m[1]} h`],
  [/^(.+) için bu değer olağan dışı görünüyor\.$/, (m) => `Este valor parece inusual para ${m[1]}.`],
  [/^Kum \+ silt \+ kil toplamı %(.+) çıktı; %100 olmalı\. Değerleri kontrol edin\.$/, (m) => `Arena + limo + arcilla suman ${m[1]} %; deberían sumar 100 %. Revise los valores.`],
  [/^(.+) bitkisinde (.+) noksanlığı$/, (m, t) => `Carencia de ${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1)).toLocaleLowerCase('es-ES')} en ${t(m[1]).toLocaleLowerCase('es-ES')}`],
  [/^(.+) bitkisinde (.+)$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} en ${t(m[1]).toLocaleLowerCase('es-ES')}`],
  [/^(.+) bitkisinde$/, (m, t) => `en ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1)).toLocaleLowerCase('es-ES')}`],
  [/^Azotlu gübre miktarını biraz azaltın; her 1\.000 m³ su ≈ (.+) kg azot getirir\.$/, (m) => `Reduzca un poco el abono nitrogenado; cada 1.000 m³ de agua aportan ≈ ${m[1]} kg de nitrógeno.`],
  [/^([A-Z][A-Za-z]{0,2}\d*) \((.+) Bünyeli\)$/, (m) => `${m[1]} (${m[2]})`],
  [/^([\d.,]+)( puan| [^\s(]+)? (eksik|fazla) \(%([\d.,]+)\)$/, (m) => `${m[1]}${m[2] === ' puan' ? ' puntos' : m[2] ?? ''} ${m[3] === 'eksik' ? 'por debajo' : 'por encima'} (${m[4]} %)`],
  [/^(.+) noksanlığı$/, (m, t) => `Carencia de ${t(m[1]).toLocaleLowerCase('es-ES')}`],
  [/^(.+) bu tuzluluktan etkilenmez\.$/, (m, t) => `${t(m[1])}: esta salinidad no le afecta.`],
  [/^Bu tuzlulukta (.+) için beklenen verim yaklaşık %(\d+) \(tuzsuz suya göre\)\.$/, (m, t) => `Con esta salinidad, el rendimiento esperado de ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1)).toLocaleLowerCase('es-ES')} es de aproximadamente el ${m[2]} % (respecto a agua sin sal).`],
  [/^(.+) tuza (.+)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} a la sal.`],
  [/^(.+) bora (.+) \(sınır (.+)–(.+) mg\/l\)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} al boro (límite ${m[3]}–${m[4]} mg/l).`],
  [/^Toprağa ya da suya jips verin: .*\(sizde ≈ (.+) kg \/ 1\.000 m³\)\.$/, (m) => `Aporte yeso al suelo o al agua: por cada 1 me/l de RSC, unos 86 kg de yeso puro por cada 1.000 m³ de agua (en su caso ≈ ${m[1]} kg / 1.000 m³).`],
  [/^Bitkinin ihtiyacından yaklaşık %(\d+) fazla su verin \(yıkama suyu\); tuz kök bölgesinden uzaklaşır\.$/, (m) => `Aporte aproximadamente un ${m[1]} % más de agua de lo que necesita el cultivo (agua de lavado); así la sal se aleja de las raíces.`],
  [/^Bu su için (.+) sulama daha uygun; imkânınız varsa geçmeyi düşünün\.$/, (m, t) => `Para esta agua es más adecuado el riego por ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1)).toLocaleLowerCase('es-ES')}; si puede, plantéese el cambio.`],
  [/^Sodyum ya da klorür yüksek \((.+) me\/l\): yaprak yanığı yapabilir; yalnızca akşam ve gece sulayın\.$/, (m) => `Sodio o cloruro altos (${m[1]} me/l): puede quemar las hojas; riegue solo al atardecer y de noche.`],
];
